import { Decoration } from '@codemirror/view';
import { getWrapFormatSpec } from '../inlineFormatSpec';
import type { MarkdownNodeDecorator } from './types';

// Inline code (`code`) and fenced code blocks. Syntax highlighting of the
// fenced body is handled by lang-markdown's nested parsing + markdownHighlight;
// this decorator only supplies the visual chrome: an inline-code background,
// per-line block styling, and conceal of the backtick fences / info string when
// the block is not being edited.

const codeSpec = getWrapFormatSpec('code');
const inlineCodeMark = Decoration.mark({ class: codeSpec.contentClass });
const conceal = Decoration.replace({});
const codeFenceMark = Decoration.mark({ class: 'cm-gn-code-fence' });
const codeBlockLine = Decoration.line({ class: 'cm-gn-code-block-line' });
const codeBlockLineStart = Decoration.line({ class: 'cm-gn-code-block-line-start' });
const codeBlockLineEnd = Decoration.line({ class: 'cm-gn-code-block-line-end' });

export const decorateCodeBlocks: MarkdownNodeDecorator = (ctx, node) => {
  if (node.name === 'InlineCode') {
    decorateInline(ctx, node);
    return;
  }
  if (node.name === 'FencedCode') {
    decorateFenced(ctx, node);
  }
};

const decorateInline: MarkdownNodeDecorator = (ctx, node) => {
  const { from, to } = node;
  ctx.decorations.push(inlineCodeMark.range(from, to));

  if (ctx.selectionOverlaps(from, to)) {
    return;
  }

  for (let child = node.node.firstChild; child; child = child.nextSibling) {
    if (child.name === codeSpec.markerNode && child.to > child.from) {
      ctx.decorations.push(conceal.range(child.from, child.to));
    }
  }
};

const decorateFenced: MarkdownNodeDecorator = (ctx, node) => {
  const { view, decorations } = ctx;
  const startLine = view.state.doc.lineAt(node.from);
  const endLine = view.state.doc.lineAt(node.to);
  const active = ctx.selectionOverlaps(startLine.from, endLine.to);

  for (let lineNumber = startLine.number; lineNumber <= endLine.number; lineNumber++) {
    const line = view.state.doc.line(lineNumber);
    decorations.push(codeBlockLine.range(line.from));
    if (lineNumber === startLine.number) {
      decorations.push(codeBlockLineStart.range(line.from));
    }
    if (lineNumber === endLine.number) {
      decorations.push(codeBlockLineEnd.range(line.from));
    }
  }

  // Conceal the opening/closing fences and the info string unless editing.
  for (let child = node.node.firstChild; child; child = child.nextSibling) {
    if (child.name === 'CodeMark' || child.name === 'CodeInfo') {
      if (child.to > child.from) {
        decorations.push((active ? codeFenceMark : conceal).range(child.from, child.to));
      }
    }
  }
};

import { Decoration } from '@codemirror/view';
import type { SyntaxNode } from '@lezer/common';
import type { EditorView } from '@codemirror/view';
import type { Range } from '@codemirror/state';
import type { MarkdownNodeDecorator } from './types';

// Blockquotes: a left-border line decoration per quoted line, italic content,
// and concealed `>` markers unless the selection touches the quote.

const quoteLine = Decoration.line({ class: 'cm-gn-quote-line' });
const quoteContent = Decoration.mark({ class: 'cm-gn-quote-content' });
const concealMark = Decoration.replace({});

function concealQuoteMarks(
  node: SyntaxNode,
  view: EditorView,
  decorations: Range<Decoration>[]
): void {
  for (let child = node.firstChild; child; child = child.nextSibling) {
    if (child.name === 'QuoteMark') {
      const line = view.state.doc.lineAt(child.from);
      const markEnd = Math.min(child.to + 1, line.to);
      if (markEnd > child.from) {
        decorations.push(concealMark.range(child.from, markEnd));
      }
    }
    if (child.name === 'Blockquote') {
      concealQuoteMarks(child, view, decorations);
    }
  }
}

export const decorateBlockquote: MarkdownNodeDecorator = (ctx, node) => {
  if (node.name !== 'Blockquote') {
    return;
  }

  const { view, decorations } = ctx;
  const startLine = view.state.doc.lineAt(node.from);
  const endLine = view.state.doc.lineAt(node.to);

  for (let lineNumber = startLine.number; lineNumber <= endLine.number; lineNumber++) {
    decorations.push(quoteLine.range(view.state.doc.line(lineNumber).from));
  }

  decorations.push(quoteContent.range(node.from, node.to));

  if (!ctx.selectionOverlaps(node.from, node.to)) {
    concealQuoteMarks(node.node, view, decorations);
  }
};

import type { Range } from '@codemirror/state';
import type { Decoration, EditorView } from '@codemirror/view';
import type { SyntaxNodeRef } from '@lezer/common';

// Context handed to each decorator while the markdown view plugin walks the
// syntax tree a single time. Decorators push ranges onto `decorations`; the
// view plugin sorts them and builds the final RangeSet. `selectionOverlaps`
// drives marker conceal (see conceal.ts).
export interface MarkdownDecorationContext {
  view: EditorView;
  decorations: Range<Decoration>[];
  selectionOverlaps: (from: number, to: number) => boolean;
}

// A decorator inspects a single syntax-tree node and contributes decorations.
// It returns nothing; matching on `node.name` is the decorator's responsibility.
export type MarkdownNodeDecorator = (ctx: MarkdownDecorationContext, node: SyntaxNodeRef) => void;

import { Decoration, EditorView, WidgetType } from '@codemirror/view';
import type { SyntaxNode } from '@lezer/common';
import type { Range } from '@codemirror/state';
import type { MarkdownNodeDecorator } from './types';

// Links: when the selection is outside the link, the raw `[text](url)` markdown
// is replaced by a styled, clickable span carrying the URL in a hidden tooltip
// element. The external-link click handler in editor.ts reads that tooltip text
// (scoped to `.cm-gn-link-styled`) to resolve the URL — keep the class names and
// tooltip element in sync with `findRenderedMarkdownLinkUrl`. When the selection
// overlaps the link, the raw markdown is revealed with marker styling so it can
// be edited.

const linkText = Decoration.mark({ class: 'cm-gn-link-text' });
const linkMarker = Decoration.mark({ class: 'cm-gn-link-marker' });
const linkUrl = Decoration.mark({ class: 'cm-gn-link-url' });

interface ParsedLink {
  text: string;
  url: string;
  title?: string;
}

function parseLinkMarkdown(content: string): ParsedLink | null {
  const match = content.match(/^\[([^\]]*)\]\(([^"\s)]+)(?:\s+"([^"]*)")?\s*\)$/);
  if (!match) {
    return null;
  }
  const result: ParsedLink = { text: match[1] ?? '', url: match[2] };
  if (match[3] !== undefined) {
    result.title = match[3];
  }
  return result;
}

class LinkTextWidget extends WidgetType {
  constructor(
    readonly text: string,
    readonly url: string,
    readonly from: number,
    readonly to: number,
    readonly title?: string
  ) {
    super();
  }

  override eq(other: LinkTextWidget): boolean {
    return (
      other.text === this.text &&
      other.url === this.url &&
      other.from === this.from &&
      other.to === this.to &&
      other.title === this.title
    );
  }

  toDOM(view: EditorView): HTMLElement {
    const span = document.createElement('span');
    span.className = 'cm-gn-link-styled';
    span.dataset.linkFrom = String(this.from);
    span.dataset.linkTo = String(this.to);
    span.textContent = this.text;
    span.style.cursor = 'pointer';
    if (this.title) {
      span.title = this.title;
    }

    const tooltip = document.createElement('span');
    tooltip.className = 'cm-gn-link-tooltip';
    tooltip.textContent = this.url;
    span.appendChild(tooltip);

    span.addEventListener('mouseenter', () => tooltip.classList.add('cm-gn-link-tooltip-visible'));
    span.addEventListener('mouseleave', () => tooltip.classList.remove('cm-gn-link-tooltip-visible'));

    span.addEventListener('click', (event) => {
      if (event.ctrlKey || event.metaKey) {
        // Let the capture-phase external-link handler in editor.ts open it.
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      view.dispatch({ selection: { anchor: this.from, head: this.to }, scrollIntoView: true });
      view.focus();
    });

    return span;
  }

  override ignoreEvent(event: Event): boolean {
    return event.type !== 'click' && event.type !== 'mouseenter' && event.type !== 'mouseleave';
  }
}

function decorateRawLink(node: SyntaxNode, view: EditorView, decorations: Range<Decoration>[]): void {
  const content = view.state.sliceDoc(node.from, node.to);
  decorations.push(linkMarker.range(node.from, node.from + 1));

  const bracketParen = content.indexOf('](');
  if (bracketParen === -1) {
    return;
  }
  if (bracketParen > 1) {
    decorations.push(linkText.range(node.from + 1, node.from + bracketParen));
  }
  decorations.push(linkMarker.range(node.from + bracketParen, node.from + bracketParen + 2));

  const urlChild = node.getChild('URL');
  if (urlChild) {
    decorations.push(linkUrl.range(urlChild.from, urlChild.to));
  }
  decorations.push(linkMarker.range(node.to - 1, node.to));
}

export const decorateLink: MarkdownNodeDecorator = (ctx, node) => {
  if (node.name !== 'Link') {
    return;
  }

  const { view, decorations } = ctx;
  const parsed = parseLinkMarkdown(view.state.sliceDoc(node.from, node.to));
  if (!parsed) {
    return;
  }

  if (ctx.selectionOverlaps(node.from, node.to)) {
    decorateRawLink(node.node, view, decorations);
    return;
  }

  decorations.push(
    Decoration.replace({
      widget: new LinkTextWidget(parsed.text, parsed.url, node.from, node.to, parsed.title)
    }).range(node.from, node.to)
  );
};
